  r := security.api_field_dictionary_sync_v1('v3', 'v3.0', (
    select jsonb_agg(jsonb_build_object(
             'api_surface', case x->>0 when 'w' then 'website' when 'z' then 'zoho' else 'shared' end,
             'endpoint', x->>1, 'field_path', x->>2, 'data_type', x->>3, 'is_nullable', (x->>4)::int = 1,
             'description', c->'d'->>((x->>5)::int),
             'allowed_values', case when jsonb_typeof(x->6) = 'array' then x->6 end,
             'req_ids', case when jsonb_typeof(x->7) = 'array' then x->7 else '[]'::jsonb end) order by o)
    from jsonb_array_elements(c->'f') with ordinality t(x, o)));
  raise notice 'api field dictionary: %', r;
end $load$;

-- Post-check: every listed field is held and current; the destination action is described on both APIs
do $k$ begin
  if (select count(*) from ref.api_field_dictionary where version = 'v3' and deprecated_in is null) < 2071 then
    raise exception 'post-check: % current v3 fields (expected at least 2,071)', (select count(*) from ref.api_field_dictionary where version = 'v3' and deprecated_in is null);
  end if;
  if (select count(*) from ref.api_field_dictionary where version = 'v3' and endpoint = 'destination' and deprecated_in is null) <> 148 then
    raise exception 'post-check: % destination fields (expected 148: 74 per API)', (select count(*) from ref.api_field_dictionary where version = 'v3' and endpoint = 'destination' and deprecated_in is null);
  end if;
end $k$;
